package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.security.crypto.password.PasswordEncoder; import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
class ReauthenticationServiceTest {
 ReauthenticationTokenDAO tokens=mock(ReauthenticationTokenDAO.class); AuthIdentityDAO identities=mock(AuthIdentityDAO.class); IdentityResolver users=mock(IdentityResolver.class); ClienteDAO clients=mock(ClienteDAO.class); EntrenadorDAO trainers=mock(EntrenadorDAO.class); PasswordEncoder passwords=mock(PasswordEncoder.class); ReauthenticationProperties props=new ReauthenticationProperties(); AuthenticatedUser user=new AuthenticatedUser(UUID.randomUUID(),"me@test",Role.CLIENTE); ReauthenticationService service;
 @BeforeEach void setup(){props.setTtlMinutes(5);service=new ReauthenticationService(tokens,identities,users,clients,trainers,passwords,props,Clock.fixed(Instant.parse("2026-09-30T00:00:00Z"),ZoneOffset.UTC));when(users.findByIdAndRole(user.userId(),user.role())).thenReturn(Optional.of(user));}
 @Test void passwordReauthIssuesOpaqueTokenBoundToTarget(){Cliente c=mock(Cliente.class);when(identities.existsByUserIdAndRoleAndProviderAndActiveTrue(user.userId(),user.role(),AuthProvider.LOCAL)).thenReturn(true);when(clients.findById(user.userId())).thenReturn(Optional.of(c));when(c.getContrasena()).thenReturn("hash");when(passwords.matches("password","hash")).thenReturn(true);ReauthTokenResponse r=service.password(user,"password",AuthProvider.GOOGLE);assertNotNull(r.reauthToken());assertEquals(300,r.expiresIn());verify(tokens).save(argThat(t->t.getTargetProvider()==AuthProvider.GOOGLE&&!t.getTokenHash().equals(r.reauthToken())));}
 @Test void passwordFailsWithoutLocalOrWithBadPassword(){when(identities.existsByUserIdAndRoleAndProviderAndActiveTrue(user.userId(),user.role(),AuthProvider.LOCAL)).thenReturn(false);assertThrows(LocalIdentityNotAvailableException.class,()->service.password(user,"x",AuthProvider.GOOGLE));when(identities.existsByUserIdAndRoleAndProviderAndActiveTrue(user.userId(),user.role(),AuthProvider.LOCAL)).thenReturn(true);when(clients.findById(user.userId())).thenReturn(Optional.empty());assertThrows(org.springframework.security.authentication.BadCredentialsException.class,()->service.password(user,"x",AuthProvider.GOOGLE));}
 @Test void providerMustBelongToCurrentUserAndCannotMatchTarget(){AuthIdentity google=new AuthIdentity(user.userId(),user.role(),AuthProvider.GOOGLE,"sub",null,Instant.now());when(identities.findByProviderAndProviderSubject(AuthProvider.GOOGLE,"sub")).thenReturn(Optional.of(google));assertNotNull(service.provider(user,new VerifiedSocialIdentity(AuthProvider.GOOGLE,"sub","x@test",null,null),AuthProvider.APPLE).reauthToken());assertThrows(InvalidReauthenticationTokenException.class,()->service.provider(user,new VerifiedSocialIdentity(AuthProvider.GOOGLE,"sub","x@test",null,null),AuthProvider.GOOGLE));AuthenticatedUser other=new AuthenticatedUser(UUID.randomUUID(),"other@test",Role.CLIENTE);AuthIdentity foreign=new AuthIdentity(other.userId(),other.role(),AuthProvider.APPLE,"foreign",null,Instant.now());when(identities.findByProviderAndProviderSubject(AuthProvider.APPLE,"foreign")).thenReturn(Optional.of(foreign));assertThrows(InvalidReauthenticationTokenException.class,()->service.provider(user,new VerifiedSocialIdentity(AuthProvider.APPLE,"foreign",null,null,null),AuthProvider.GOOGLE));}
 @Test void consumedExpiredWrongUserAndWrongTargetTokensFail(){ReauthenticationToken token=new ReauthenticationToken(PasswordResetService.hash("raw"),user.userId(),user.role(),AuthProvider.GOOGLE,Instant.now(),Instant.parse("2026-10-01T00:00:00Z"));when(tokens.findLockedByTokenHash(anyString())).thenReturn(Optional.of(token));service.consumeForUnlink(user,AuthProvider.GOOGLE,"raw");assertNotNull(token.getConsumedAt());assertThrows(InvalidReauthenticationTokenException.class,()->service.consumeForUnlink(user,AuthProvider.GOOGLE,"raw"));}
}
